class Atmosphere { art: WeatherArt; sun: T.DirectionalLight; hemi: T.HemisphereLight; rain: T.LineSegments; smoke: T.Points; steam: T.Points; weather: 'rain' | 'overcast' | 'fog' | 'clear' = 'rain'; override: string | null = null; rainPositions = new Float32Array(1500 * 6); smokePositions = new Float32Array(220 * 3); steamPositions = new Float32Array(90 * 3); age = new Float32Array(220); steamAge = new Float32Array(90); steamAlpha = new Float32Array(90); sky = new T.Color(); constructor(public scene: T.Scene, public city: City) { this.art=new WeatherArt(scene,city); scene.fog = new T.FogExp2('#68787b', .011); scene.background = new T.Color('#71858b'); this.hemi = new T.HemisphereLight('#ffffff', '#e8e8e8', 1.6); scene.add(this.hemi); this.sun = new T.DirectionalLight('#f4cd9a', 2.3); this.sun.position.set(-35, 55, 20); this.sun.castShadow = true; this.sun.shadow.mapSize.set(2048, 2048); this.sun.shadow.camera.left = -65; this.sun.shadow.camera.right = 65; this.sun.shadow.camera.top = 85; this.sun.shadow.camera.bottom = -60; this.sun.shadow.camera.far = 190; this.sun.shadow.normalBias = .04; this.sun.shadow.bias = -.0003; scene.add(this.sun); scene.add(this.sun.target); for (let i = 0; i < 1500; i++) { const j=i*6;this.rainPositions[j] = (random() - .5) * 100; this.rainPositions[j + 1] = random() * 40; this.rainPositions[j + 2] = (random() - .5) * 100;this.rainPositions[j+3]=this.rainPositions[j]-.015;this.rainPositions[j+4]=this.rainPositions[j+1]+.26;this.rainPositions[j+5]=this.rainPositions[j+2]; } const rg = new T.BufferGeometry(); rg.setAttribute('position', new T.BufferAttribute(this.rainPositions, 3)); this.rain = new T.LineSegments(rg, new T.LineBasicMaterial({ color: '#b3cacf', transparent: true, opacity: .24, depthWrite: false })); this.rain.frustumCulled = false; scene.add(this.rain); const canvas = document.createElement('canvas'); canvas.width = canvas.height = 64; const c = canvas.getContext('2d')!; c.fillStyle = '#e0e8d9'; c.strokeStyle = '#526c6c80'; c.lineWidth = 1.4; c.beginPath(); for (let i=0;i<11;i++) { const a=i/11*Math.PI*2; const r=25+Math.sin(i*7)*4; const px=32+Math.cos(a)*r, py=32+Math.sin(a)*r; if(i===0)c.moveTo(px,py);else c.lineTo(px,py); } c.closePath(); c.fill(); c.stroke(); const texture = new T.CanvasTexture(canvas); const sg = new T.BufferGeometry(); sg.setAttribute('position', new T.BufferAttribute(this.smokePositions, 3)); this.smoke = new T.Points(sg, new T.PointsMaterial({ color: '#3b3733', map: texture, size: 7.5, transparent: true, opacity: .4, depthWrite: false })); this.smoke.frustumCulled = false; scene.add(this.smoke); for (let i = 0; i < 220; i++) this.age[i] = random() * 15; const steamG = new T.BufferGeometry(); steamG.setAttribute('position', new T.BufferAttribute(this.steamPositions, 3)); this.steam = new T.Points(steamG, new T.PointsMaterial({ color: '#c7d9d6', map: texture, size: 1.4, transparent: true, opacity: .3, depthWrite: false })); steamG.setAttribute('plumeOpacity',new T.BufferAttribute(this.steamAlpha,1)); const steamMaterial=this.steam.material as T.PointsMaterial; steamMaterial.onBeforeCompile=shader=>{ shader.vertexShader='attribute float plumeOpacity; varying float vPlumeOpacity;
'+shader.vertexShader; shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>
vPlumeOpacity=plumeOpacity;'); shader.fragmentShader='varying float vPlumeOpacity;
'+shader.fragmentShader; shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>
diffuseColor.a*=vPlumeOpacity;'); }; steamMaterial.customProgramCacheKey=()=> 'terra-pressure-release'; scene.add(this.steam); this.steam.frustumCulled = false; for (let i = 0; i < 90; i++) this.steamAge[i] = random() * 5; } update(dt: number, time: number, camera: T.Camera, preview = false) { const day = preview ? .42 : this.city.economy.state.day; const phase = Math.sin(day * Math.PI * 2 - Math.PI / 2); const daylight = T.MathUtils.smoothstep(phase, -.25, .7); const weather = this.override ?? (['overcast','rain','fog','overcast','clear','rain'][Math.floor(time/110)%6]); this.weather = weather as typeof this.weather; this.city.raining = weather === 'rain'; const stage = this.city.economy.stage; // Art-directed light keys: lit color, shadow color, sky and haze per weather and hour. const dusk = Math.max(0, 1 - Math.abs(day - .74) * 10) + Math.max(0, 1 - Math.abs(day - .26) * 14) * .6; const smog = Math.max(0, 1 - stage / 3.5) * (weather === 'clear' ? .75 : 1); const key = keys[weather as keyof typeof keys] ?? keys.overcast; tone.lit.value.setRGB(...keys.night.lit).lerp(C.setRGB(...key.lit), daylight).lerp(C.setRGB(1.12, .8, .6), dusk * .7).lerp(C.setRGB(.95, .93, .88), smog * .2 * daylight); tone.shade.value.setRGB(...keys.night.shade).lerp(C.setRGB(...key.shade), daylight).lerp(C.setRGB(.52, .45, .76), dusk * .6).lerp(C.setRGB(.66, .64, .7), smog * .3 * daylight); tone.rim.value.set(P.warm.lamp); this.hemi.intensity = .28 + daylight

