function flowMaterial(color: string, kind: 'water' | 'aether', opacity: number, clock: FlowClock = flowClock) { const aether = kind === 'aether'; const m = new T.MeshBasicMaterial({ color, transparent: true, opacity, depthWrite: false, fog: false, side: T.DoubleSide, blending: aether ? T.AdditiveBlending : T.NormalBlending, polygonOffset: true, polygonOffsetFactor: -2 }); m.onBeforeCompile = sh => { sh.uniforms.flowTime = clock.time; sh.uniforms.flowFront = clock.front; sh.vertexShader = 'varying vec2 vFlow;
