 diffuseColor.rgb *= .45 + 1.1 * pulse + 2.2 * crest; diffuseColor.a *= reach * (1. - abs(vFlow.y - .5) * 1.4);' : 'float ripple = .5 + .5 * sin(vFlow.x * 6. - flowTime * 4.5 + sin(vFlow.y * 9. + flowTime * 1.7) * 1.4);
 diffuseColor.rgb *= .8 + .4 * ripple; diffuseColor.a *= reach;'}`); }; m.customProgramCacheKey = () => 'terra-flow-' + kind; return m; }

density(){const g=this.section(); const slogan=(text:string,color:string,w:number,h:number)=>{const c=document.createElement('canvas');c.width=512;c.height=Math.round(512*h/w);const x=c.getContext('2d')!;x.fillStyle=color;x.textAlign='center';x.textBaseline='middle'; const lines=text.split('/');const fs=Math.min(c.height/lines.length*.78,120);x.font=`900 ${fs}px "Marker Felt","Chalkduster",fantasy`;lines.forEach((l,i)=>{x.save();x.translate(256,(i+.5)*c.height/lines.length);x.rotate(-.04+i*.03);x.fillText(l,0,0,480);x.restore();}); for(let i=0;i<8;i++){x.fillRect(80+Math.random()*350,c.height*.55+Math.random()*c.height*.4,3,10+Math.random()*30);} const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.anisotropy=8;return new T.MeshBasicMaterial({map:t,transparent:true,opacity:.85,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-3});}; const slogans=[['WHO OWNS/THE STEAM?','#e9e1cf'],['NO EMBER IS/TOO SMALL','#d8b86a'],['KEEP THE/LAMPS BURNING','#e9e1cf'],['PAY WHAT/YOU OWE','#c25a45'],['FINCH/LIES','#e9e1cf']]; this.city.housingFrontages.forEach((h,i)=>{const f=new T.Group();f.position.set(h.x,0,h.z);f.rotation.y=h.yaw;g.add(f);const w=h.width; {const [t,c]=slogans[i%slogans.length];const m=new T.Mesh(new T.PlaneGeometry(4.2,1.35),slogan(t,c,4.2,1.35));m.position.set((i%3-1)*1.2,7.35,.32);f.add(m);} // Wrought-iron balconies on corbels: scroll balusters and a curled bracket either side. for(const [bx,by] of (i%2?[[-w*.29,7.6]]:[[w*.29,7.6],[-w*.29,11.1]]) as [number,number][]){if(by>h.height-2.5)continue;box(f,bx,by,.55,2.3,.1,1,mats.stone); for(let k=0;k<=8;k++){const px=bx-1.1+k*.275;box(f,px,by+.5,1.02,.03,.9,.03,mats.iron);if(k%2){const s=torus(f,px+.13,by+.72,1.02,.11,.018,mats.iron);s.rotation.y=0;}} box(f,bx,by+.98,1.02,2.3,.06,.06,mats.iron);for(const side of [-1,1]){box(f,bx+side*1.15,by+.5,.55,.03,.9,.95,mats.iron);const sc=torus(f,bx+side*.9,by-.35,.35,.28,.03,mats.iron);sc.rotation.y=Math.PI/2;}}}); // Clutter pockets hug the walls: crates, sacks, a broken chair, a barrow. Never in the lanes. const pocket=(x:number,z:number,yaw:number,k:number)=>{const p=new T.Group();p.position.set(x,0,z);p.rotation.y=yaw;g.add(p);crate(p,0,0,0,.8);crate(p,.05,.8,.05,.55);crate(p,.95,0,.2,.6); for(let i=0;i<3;i++){const sk=sphere(p,-.8+i*.3,.3,.4+(i%2)*.2,1,mats.cream);sk.scale.set(.32,.28,.26);} if(k%2){box(p,1.8,.45,.2,.5,.06,.5,mats.wood);box(p,1.6,.7,.2,.06,.5,.5,mats.wood);box(p,1.95,.22,.2,.05,.45,.05,mats.wood);} else{box(p,1.9,.5,0,.9,.25,1.3,mats.wood);torus(p,1.9,.3,.7,.3,.05,mats.iron).rotation.y=Math.PI/2;beam(p,V(1.9,.55,-.6),V(1.9,.9,-1.4),.03,mats.wood);} this.city.localCollider(p,.8,.2,3.2,1.6,1.6);}; [[-41.6,41,Math.PI/2],[-41.6,-2,Math.PI/2],[-41.6,-26,Math.PI/2],[-26.4,35,-Math.PI/2],[-26.4,-12,-Math.PI/2],[26.2,20,Math.PI/2],[26.2,47,Math.PI/2]].forEach(([x,z,y],k)=>pocket(x,z,y,k)); // Sun shafts through the haze where cross streets cut the canyon. const c=document.createElement('canvas');c.width=64;c.height=256;const x=c.getContext('2d')!;const gr=x.createLinearGradient(0,0,0,256);gr.addColorStop(0,'rgba(255,236,190,0)');gr.addColorStop(.25,'rgba(255,236,190,.55)');gr.addColorStop(1,'rgba(255,236,190,0)');x.fillStyle=gr;x.fillRect(0,0,64,256); const hx=x.createLinearGradient(0,0,64,0);hx.addColorStop(0,'rgba(0,0,0,1)');hx.addColorStop(.5,'rgba(0,0,0,0)');hx.addColorStop(1,'rgba(0,0,0,1)');x.globalCompositeOperation='destination-out';x.fillStyle=hx;x.fillRect(0,0,64,256); this.shaftMat=new T.MeshBasicMaterial({map:new T.CanvasTexture(c),transparent:true,blending:T.AdditiveBlending,depthWrite:false,side:T.DoubleSide,opacity:.5,fog:false}); // Shafts belong to the middle distance: they fade out near the eye instead of washing the frame. this.shaftMat.onBeforeCompile=sh=>{sh.vertexShader='varying float vEyeDist;
