class TerraEdge { root = new T.Group(); fall: T.Mesh; water: T.MeshBasicMaterial; private waterBase = new T.Color('#dff5f2'); isle = new T.Group(); farIsle!: T.Group; eastIsle!: T.Group; birds: T.InstancedMesh; waterTime = { value: 0 }; constructor(public city: City) { city.root.add(this.root); const g = new T.Group(); this.root.add(g); const I = ancientMats.ivory, G = ancientMats.gold; // The plate Terra stands on: the ward and the far ring sit on it, with bastions and the // terrace promontory breaking the rim. Ninety metres of cliff; the haze takes the rest. const rim: [number, number][] = [[-150, -150], [150, -150], [150, EDGE_Z], [78, EDGE_Z], [78, 90], [62, 90], [62, EDGE_Z], [TERRACE.half, EDGE_Z], [TERRACE.half, TERRACE.z], [-TERRACE.half, TERRACE.z], [-TERRACE.half, EDGE_Z], [-62, EDGE_Z], [-62, 90], [-78, 90], [-78, EDGE_Z], [-150, EDGE_Z]]; const depth = 90, slab = new T.ExtrudeGeometry(new T.Shape(rim.map(([x, z]) => new T.Vector2(x, -z))), { depth, bevelEnabled: false }); const uv = slab.attributes.uv; for (let i = 0; i < uv.count; i++) uv.setXY(i, uv.getX(i) * .08, uv.getY(i) * .08); const plate = new T.Mesh(slab, [mats.dirt, rock]); plate.rotation.x = -Math.PI / 2; plate.position.y = -depth - .02; plate.receiveShadow = true; this.root.add(plate); // The arrival terrace: pale paving past the tenements, an ivory balustrade on the lip. box(g, 0, .05, (78.4 + TERRACE.z) / 2, TERRACE.half * 2, .1, TERRACE.z - 78.4, mats.warmStone); for (let x = -21; x <= 21; x += 6) box(g, x, .105, 86.3, .08, .012, 4.4, G); const baluster = new T.LatheGeometry([[0, 0], [.1, 0], [.07, .12], [.12, .38], [.06, .62], [.09, .72], [0, .74]].map(([r, y]) => new T.Vector2(r, y)), 8); const rail = (x0: number, x1: number, z0: number, z1: number) => { const len = Math.hypot(x1 - x0, z1 - z0), n = Math.floor(len / .42), yaw = Math.atan2(x1 - x0, z1 - z0); box(g, (x0 + x1) / 2, 1.02, (z0 + z1) / 2, .36, .12, len + .3, I).rotation.y = yaw; box(g, (x0 + x1) / 2, .16, (z0 + z1) / 2, .44, .14, len + .3, I).rotation.y = yaw; for (let k = 1; k < n; k++) { const t = k / n, m = new T.Mesh(baluster, I); m.position.set(x0 + (x1 - x0) * t, .23, z0 + (z1 - z0) * t); g.add(m); } }; rail(-TERRACE.half, TERRACE.half, TERRACE.z - .3, TERRACE.z - .3); for (const s of [-1, 1]) rail(s * (TERRACE.half - .2), s * (TERRACE.half - .2), EDGE_Z - .2, TERRACE.z - .3); for (const x of [-TERRACE.half + .2, -8, 8, TERRACE.half - .2]) { box(g, x, .7, TERRACE.z - .3, .62, 1.4, .62, I); box(g, x, 1.45, TERRACE.z - .3, .74, .1, .74, G); torus(g, x, 1.85, TERRACE.z - .3, .2, .03, G); sphere(g, x, 1.85, TERRACE.z - .3, .09, mats.glow); } city.collider(0, TERRACE.z - .25, TERRACE.half * 2 + .4, .6, 1.3); for (const s of [-1, 1]) city.collider(s * (TERRACE.half - .2), (EDGE_Z + TERRACE.z) / 2, .6, TERRACE.z - EDGE_Z, 1.3); // The spillway: an ivory trough reaching past the lip, and a fall that never lands. const sx = -9; box(g, sx, -.35, 92, 1.7, .5, 7, I); for (const dx of [-.82, .82]) box(g, sx + dx, -.02, 92, .12, .3, 7, I); torus(g, sx, -.35, 95.5, .7, .09, G); for (const z of [89.5, 94.5]) box(g, sx, -1.6, z, .5, 2.4, .5, I).rotation.x = z > 92 ? .5 : .2; const water = this.water = new T.MeshBasicMaterial({ color: '#dff5f2', transparent: true, opacity: .92, depthWrite: false, side: T.DoubleSide }); water.onBeforeCompile = sh => { sh.uniforms.waterTime = this.waterTime; sh.vertexShader = 'varying vec2 vFall;
